// Source-bound classical baselines and a candidate-prefix/rho composition.
// Upstream rho/precomp algorithms are unchanged; all EC operations use dec::Ops.
#include "../candidate/decoder.hpp"
#include "vendor/include/cryptanalysis/ca_rho.h"
#include "vendor/include/cryptanalysis/ca_precomp.h"
#include <chrono>
#include <ctime>
#include <memory>
#include <type_traits>
#include <sys/resource.h>
#include <time.h>

namespace bench {
using dec::U;using lab::I;using lab::Point;
constexpr const char* scope="larger_solver_validation";
constexpr const char* track="solver-baselines";
constexpr const char* upstream="379faa0f1e38facd9c8fdfc527f0b89518cf2e70";
struct Clock {timespec c{};std::chrono::steady_clock::time_point w;
 Clock():w(std::chrono::steady_clock::now()){lab::require(clock_gettime(CLOCK_PROCESS_CPUTIME_ID,&c)==0,"process clock unavailable");}
 long double cpu()const{timespec q{};lab::require(clock_gettime(CLOCK_PROCESS_CPUTIME_ID,&q)==0,"process clock failure");return static_cast<long double>(q.tv_sec-c.tv_sec)+static_cast<long double>(q.tv_nsec-c.tv_nsec)/1e9L;}
 long double wall()const{return std::chrono::duration<long double>(std::chrono::steady_clock::now()-w).count();}
};
struct Aux {U hash_calls=0,equality_calls=0,negation_calls=0,canonicalization_calls=0,batch_calls=0;};
struct Adapter {ca_group g{};dec::Ops* ops;Aux aux;
 explicit Adapter(const lab::Fixture&f,dec::Ops&o);
};
static_assert(std::is_standard_layout_v<Adapter> && offsetof(Adapter,g)==0);
Adapter& adapter(const ca_group*g){return *const_cast<Adapter*>(reinterpret_cast<const Adapter*>(g));}
Point point(const ca_elem&e){lab::require(e.w[2]<=1&&e.w[3]==0,"noncanonical adapter element");return {static_cast<I>(e.w[0]),static_cast<I>(e.w[1]),e.w[2]!=0};}
ca_elem element(Point p){return {{static_cast<U>(p.x),static_cast<U>(p.y),p.inf?1U:0U,0}};}
void op(const ca_group*g,ca_elem*r,const ca_elem*a,const ca_elem*b){*r=element(adapter(g).ops->add(point(*a),point(*b)));}
void dbl(const ca_group*g,ca_elem*r,const ca_elem*a){op(g,r,a,a);}
void inv(const ca_group*g,ca_elem*r,const ca_elem*a){auto&p=adapter(g);++p.aux.negation_calls;auto q=point(*a);if(!q.inf)q.y=p.ops->minus(0,q.y);*r=element(q);}
void identity(const ca_group*,ca_elem*r){*r=element({});}
int is_identity(const ca_group*,const ca_elem*a){return point(*a).inf?1:0;}
int equal(const ca_group*g,const ca_elem*a,const ca_elem*b){++adapter(g).aux.equality_calls;return point(*a)==point(*b)?1:0;}
U hash_point(const ca_group*g,const ca_elem*a){++adapter(g).aux.hash_calls;const auto q=point(*a);return q.inf?dec::mix(0x6f726465722d6964ULL):dec::mix(static_cast<U>(q.x)^std::rotl(static_cast<U>(q.y),32)^0x706f696e742d7631ULL);}
void batch(const ca_group*g,ca_elem*r,const ca_elem*a,const ca_elem*b,std::size_t n,U*){++adapter(g).aux.batch_calls;for(std::size_t i=0;i<n;++i)op(g,r+i,a+i,b+i);}
int encode(const ca_group*g,ca_elem*r,const U*w){ca_elem q{{w[0],w[1],w[2],w[3]}};if(w[2]>1||w[3]!=0)return 0;if(!adapter(g).ops->valid(point(q)))return 0;*r=q;return 1;}
void decode(const ca_group*,U*w,const ca_elem*a){std::copy(std::begin(a->w),std::end(a->w),w);}
int valid(const ca_group*g,const ca_elem*a){return adapter(g).ops->valid(point(*a))?1:0;}
int canonical(const ca_group*g,ca_elem*a){auto&z=adapter(g);++z.aux.canonicalization_calls;auto q=point(*a);if(q.inf||q.y<=z.ops->curve.p-q.y)return 0;++z.aux.negation_calls;q.y=z.ops->minus(0,q.y);*a=element(q);return 1;}
const ca_group_vtable vt{op,dbl,inv,identity,is_identity,equal,hash_point,batch,encode,decode,valid,canonical};
Adapter::Adapter(const lab::Fixture&f,dec::Ops&o):ops(&o){g.vt=&vt;g.kind=CA_GROUP_EC;g.order=static_cast<U>(f.r);g.p=static_cast<U>(f.c.p);g.a=static_cast<U>(f.c.a);g.b=static_cast<U>(f.c.b);g.cofactor=static_cast<U>(f.N/f.r);}
std::string aux_json(const Aux&a){std::ostringstream o;o<<"{\"hash_calls\":"<<a.hash_calls<<",\"equality_calls\":"<<a.equality_calls<<",\"negation_calls\":"<<a.negation_calls<<",\"canonicalization_calls\":"<<a.canonicalization_calls<<",\"batch_calls\":"<<a.batch_calls<<'}';return o.str();}
std::string stats_json(const ca_stats&s){std::ostringstream o;o<<std::setprecision(18)<<"{\"reported_group_ops\":"<<s.group_ops<<",\"iterations\":"<<s.iterations<<",\"table_entries\":"<<s.table_entries<<",\"collisions\":"<<s.collisions<<",\"table_bytes_peak_estimate\":"<<s.bytes_peak<<",\"upstream_wall_seconds\":"<<s.seconds<<",\"threads\":"<<s.threads<<'}';return o.str();}
U ceil_sqrt(U r){U m=static_cast<U>(std::sqrt(static_cast<long double>(r)));while(m*m<r)++m;while(m>1&&(m-1)*(m-1)>=r)--m;return m;}
U nonzero_seed(U s){return s?s:1;}
U rho_seed(const lab::Fixture&f,const dec::Target&t){return nonzero_seed(f.seed^dec::hash("validation.rho.paired.v1")^dec::mix(t.ordinal+0x4125U));}
U rho_limit(const lab::Fixture&f){return 256U*ceil_sqrt(static_cast<U>(f.r))+8192U;}
U rho_effective_r(const lab::Fixture&f){const U root=static_cast<U>(std::sqrt(static_cast<long double>(f.r)))+1;const U budget=root/(48U*lab::bits(static_cast<U>(f.r)));U r=8;while(r*2<=budget&&r*2<=1024)r*=2;return r;}
U rho_effective_walks(const lab::Fixture&f){const U root=static_cast<U>(std::sqrt(static_cast<long double>(f.r)))+1;return std::max(U{1},std::min(U{256},root/(24U*lab::bits(static_cast<U>(f.r)))));}
int rho_effective_dp(const lab::Fixture&f){const long double expected=1.25L*static_cast<long double>(static_cast<U>(std::sqrt(static_cast<long double>(f.r)))+1)/1.4142L;const long double per=expected/(32.0L*static_cast<long double>(rho_effective_walks(f)));return per>=2?static_cast<int>(std::floor(std::log2(per))):0;}
struct Result {std::optional<U> scalar;ca_status status=CA_OK;ca_stats stats{};dec::Cost counters;Aux aux;long double cpu=0,wall=0;};
Result rho(const lab::Fixture&f,const dec::Target&t,dec::Ops&ops,U seed){Clock timer;const auto before=ops.cost;Adapter a(f,ops);ca_rho_params p;ca_rho_params_default(&p);p.threads=1;p.negation_map=1;p.seed=nonzero_seed(seed);p.max_ops=rho_limit(f);U scalar=0;Result z;const auto base=element(f.P),target=element(t.q);z.status=ca_rho_solve(&a.g,&base,&target,&p,&scalar,&z.stats);if(z.status==CA_OK){++ops.cost.candidate_verifications;lab::require(scalar<static_cast<U>(f.r)&&ops.scalar(f.P,scalar)==t.q,"rho returned wrong scalar");z.scalar=scalar;}z.counters=dec::difference(ops.cost,before);z.aux=a.aux;z.cpu=timer.cpu();z.wall=timer.wall();return z;}
struct Precomp {dec::Ops ops;Adapter adapter;ca_precomp_table* table=nullptr;ca_status status;ca_stats stats{};dec::Cost setup;Aux setup_aux;long double cpu=0,wall=0;int32_t dp_bits=0;U chains=0,reported_precomp_ops=0;std::uint32_t adding_steps=0;
 explicit Precomp(const lab::Fixture&f):ops(f.c),adapter(f,ops){Clock timer;ca_precomp_params p;ca_precomp_params_default(&p);p.threads=1;p.seed=nonzero_seed(f.seed^dec::hash("validation.bl.precomputation.v1"));p.max_precomp_ops=64U*static_cast<U>(f.r)+8192U;p.max_online_ops=rho_limit(f);const auto base=element(f.P);status=ca_precomp_table_new(&adapter.g,&base,&p,&table,&stats);setup=ops.cost;setup_aux=adapter.aux;cpu=timer.cpu();wall=timer.wall();if(table)ca_precomp_table_info(table,&dp_bits,&chains,&adding_steps,&reported_precomp_ops);}
 ~Precomp(){if(table)ca_precomp_table_free(table);}Precomp(const Precomp&)=delete;Precomp&operator=(const Precomp&)=delete;
 Result solve(const lab::Fixture&f,const dec::Target&t){Clock timer;const auto before=ops.cost;adapter.aux={};Result z;if(status!=CA_OK||!table)z.status=status;else{U k=0;const auto q=element(t.q);z.status=ca_precomp_table_solve(table,&q,&k,&z.stats);if(z.status==CA_OK){++ops.cost.candidate_verifications;lab::require(k<static_cast<U>(f.r)&&ops.scalar(f.P,k)==t.q,"BL returned wrong scalar");z.scalar=k;}}z.counters=dec::difference(ops.cost,before);z.aux=adapter.aux;z.cpu=timer.cpu();z.wall=timer.wall();return z;}
};
struct BSGS {using Entry=std::pair<Point,U>;std::vector<Entry> baby;Point jump;dec::Cost setup;long double cpu=0,wall=0;U m=0;
 explicit BSGS(const lab::Fixture&f){Clock timer;dec::Ops ops(f.c);m=ceil_sqrt(static_cast<U>(f.r));baby.reserve(static_cast<std::size_t>(m));Point p{};for(U j=0;j<m;++j){baby.emplace_back(p,j);p=ops.add(p,f.P);}jump=p;if(!jump.inf)jump.y=ops.minus(0,jump.y);std::sort(baby.begin(),baby.end());setup=ops.cost;cpu=timer.cpu();wall=timer.wall();}
 Result solve(const lab::Fixture&f,const dec::Target&t){Clock timer;dec::Ops ops(f.c);Result z;Point p=t.q;for(U i=0;i<m;++i){const auto it=std::lower_bound(baby.begin(),baby.end(),Entry{p,0});if(it!=baby.end()&&it->first==p){const U k=i*m+it->second;if(k<static_cast<U>(f.r)){++ops.cost.candidate_verifications;lab::require(ops.scalar(f.P,k)==t.q,"BSGS collision failed verification");z.scalar=k;break;}}p=ops.add(p,jump);}lab::require(z.scalar.has_value(),"complete BSGS failed canonical subgroup target");z.counters=ops.cost;z.stats.table_entries=baby.size();z.stats.bytes_peak=static_cast<U>(baby.capacity()*sizeof(Entry));z.cpu=timer.cpu();z.wall=timer.wall();return z;}
};
std::string nullable(std::optional<U>k){return k?std::to_string(*k):"null";}
std::string list(std::optional<U>k){return k?"["+std::to_string(*k)+"]":"[]";}
std::string status_name(const Result&z){if(z.status==CA_OK&&z.scalar)return "solved";if(z.status==CA_ERR_LIMIT||z.status==CA_ERR_NOMEM)return "censored";if(z.status==CA_ERR_INVALID||z.status==CA_ERR_INTERNAL)return "invalid";return "failed";}
std::string prefix(){return std::string("{\"scope\":")+lab::json_quote(scope)+",\"track\":"+lab::json_quote(track);}
void common_target(std::ostream&o,const lab::Fixture&f,const dec::Target&t,const std::string&method,unsigned order,const Result&z){o<<prefix()<<",\"row_kind\":\"baseline_target\",\"fixture\":"<<lab::json_quote(f.id)<<",\"target_id\":"<<lab::json_quote(t.id)<<",\"target_ordinal\":"<<t.ordinal<<",\"method\":"<<lab::json_quote(method)<<",\"execution_order\":"<<order<<",\"status\":"<<lab::json_quote(status_name(z))<<",\"upstream_status\":"<<static_cast<int>(z.status)<<",\"candidates\":"<<list(z.scalar)<<",\"candidate_verification_hits\":"<<(z.scalar?1:0)<<",\"verified_scalar\":"<<nullable(z.scalar)<<",\"counters\":"<<dec::cost_json(z.counters)<<",\"process_cpu_seconds\":"<<z.cpu<<",\"wall_seconds\":"<<z.wall<<",\"auxiliary_work\":"<<aux_json(z.aux)<<",\"upstream_stats\":"<<stats_json(z.stats)<<",\"counter_scope\":\"All EC arithmetic uses shared Ops; wrapper final checks counted. Upstream internal RNG/hash/table work is reflected in CPU, not decoder rng_draws. Upstream internal scalar checks remain charged in field/group/scalar counters.\",\"upstream_rng_draws_instrumented\":false";}
void rho_row(std::ostream&o,const lab::Fixture&f,const dec::Target&t,const std::string&method,unsigned order,const Result&z){common_target(o,f,t,method,order,z);const bool walked=!t.q.inf&&f.r>=64;o<<",\"rho_seed\":"<<rho_seed(f,t)<<",\"rho_max_ops\":"<<rho_limit(f)<<",\"negation_map_requested\":true,\"negation_map_used\":"<<(walked?"true":"false")<<",\"rho_algorithm_path\":"<<lab::json_quote(t.q.inf?"identity_shortcut":f.r<64?"tiny_linear_scan":"negation_r_adding_walk")<<",\"rho_adding_steps_effective\":"<<(walked?rho_effective_r(f):0)<<",\"rho_walks_effective\":"<<(walked?rho_effective_walks(f):0)<<",\"rho_dp_bits_effective\":"<<(walked?rho_effective_dp(f):0)<<",\"upstream_commit\":"<<lab::json_quote(upstream)<<"}\n";}
struct Hybrid {dec::Ops training_ops;long double setup_cpu=0,setup_wall=0;dec::Model model;
 explicit Hybrid(const lab::Fixture&f):training_ops(f.c),model([&]{Clock timer;auto m=dec::train(f,dec::Kind::xmod7,training_ops,false);setup_cpu=timer.cpu();setup_wall=timer.wall();return m;}()){}
 void emit(std::ostream&o,const lab::Fixture&f,const dec::Target&t,unsigned order){dec::Ops ops(f.c);ops.sqrt_z=training_ops.sqrt_z;Clock timer;const auto views=dec::make_views(f,t,model,ops);const auto r=dec::solve_candidate(f,t,model,views,8,true,ops);const auto prefix_cost=ops.cost;const long double prefix_cpu=timer.cpu();Result fallback;bool used=!r.verified.has_value();std::optional<U>answer=r.verified;if(used){fallback=rho(f,t,ops,rho_seed(f,t));answer=fallback.scalar;}Result z;z.scalar=answer;z.status=answer?CA_OK:fallback.status;z.counters=ops.cost;z.cpu=timer.cpu();z.wall=timer.wall();z.aux=fallback.aux;z.stats=fallback.stats;common_target(o,f,t,"hybrid_xmod7_exact_b8_then_rho",order,z);o<<",\"feature\":\"x_mod_7\",\"prefix_mode\":\"exact\",\"beam_width\":8,\"prefix_candidates\":"<<dec::array_json(r.search.candidates)<<",\"prefix_candidate_verification_hits\":"<<r.hits<<",\"prefix_verified_scalar\":"<<nullable(r.verified)<<",\"fallback_used\":"<<(used?"true":"false")<<",\"rho_seed\":"<<rho_seed(f,t)<<",\"rho_max_ops\":"<<rho_limit(f)<<",\"views_seed\":"<<views.seed<<",\"setup_reference\":"<<lab::json_quote(f.id+"/hybrid_xmod7_exact_b8_then_rho")<<",\"charged_setup_cache_reused\":true,\"prefix_process_cpu_seconds\":"<<prefix_cpu<<",\"stages\":{\"views\":"<<dec::cost_json(views.cost)<<",\"inference\":"<<dec::cost_json(r.inference)<<",\"verification\":"<<dec::cost_json(r.verification)<<",\"prefix_total\":"<<dec::cost_json(prefix_cost)<<",\"fallback\":"<<dec::cost_json(fallback.counters)<<"},\"fallback_process_cpu_seconds\":"<<fallback.cpu<<",\"views_process_cpu_seconds\":"<<views.cpu_seconds<<",\"inference_process_cpu_seconds\":"<<r.inference_cpu_seconds<<",\"verification_process_cpu_seconds\":"<<r.verification_cpu_seconds<<",\"fallback_wall_seconds\":"<<fallback.wall<<",\"candidate_alone_recovered\":"<<(r.verified?"true":"false")<<"}\n";}
};
void setup_rows(std::ostream&o,const lab::Fixture&f,const std::vector<dec::Target>&targets,Hybrid&h,Precomp&p,BSGS&b,const dec::Cost&validation,long double validation_cpu,long double validation_wall){
 o<<prefix()<<",\"row_kind\":\"fixture_validation\",\"method\":\"shared_public_validation\",\"fixture\":"<<lab::json_quote(f.id)<<",\"targets\":"<<targets.size()<<",\"counters\":"<<dec::cost_json(validation)<<",\"process_cpu_seconds\":"<<validation_cpu<<",\"wall_seconds\":"<<validation_wall<<"}\n";
 o<<prefix()<<",\"row_kind\":\"hybrid_setup\",\"method\":\"hybrid_xmod7_exact_b8_then_rho\",\"fixture\":"<<lab::json_quote(f.id)<<",\"targets_reusing_setup\":"<<targets.size()<<",\"diagnostics_performed\":false,\"counters\":"<<dec::cost_json(h.training_ops.cost)<<",\"process_cpu_seconds\":"<<h.setup_cpu<<",\"wall_seconds\":"<<h.setup_wall<<",\"training_samples\":"<<dec::training_samples<<",\"training_seed\":"<<h.model.training_seed<<",\"kernel_numeric_payload_bytes\":"<<2U*h.model.size()*h.model.size()*(sizeof(U)+sizeof(long double))+h.model.size()*sizeof(U)<<",\"memory_scope\":\"Kernel/count/row-mass payload only; excludes stored marginals, feature, objects, allocator and temporary buffers\",\"setup_reference\":"<<lab::json_quote(f.id+"/hybrid_xmod7_exact_b8_then_rho")<<"}\n";
 o<<prefix()<<",\"row_kind\":\"baseline_setup\",\"method\":\"bernstein_lange_precomp\",\"fixture\":"<<lab::json_quote(f.id)<<",\"targets_reusing_setup\":"<<targets.size()<<",\"status\":"<<static_cast<int>(p.status)<<",\"counters\":"<<dec::cost_json(p.setup)<<",\"process_cpu_seconds\":"<<p.cpu<<",\"wall_seconds\":"<<p.wall<<",\"upstream_stats\":"<<stats_json(p.stats)<<",\"auxiliary_work\":"<<aux_json(p.setup_aux)<<",\"dp_bits\":"<<p.dp_bits<<",\"stored_chains\":"<<p.chains<<",\"adding_steps\":"<<p.adding_steps<<",\"max_precomp_ops\":"<<64U*static_cast<U>(f.r)+8192U<<",\"max_online_ops\":"<<rho_limit(f)<<",\"coverage\":1,\"threads\":1,\"upstream_commit\":"<<lab::json_quote(upstream)<<",\"setup_reference\":"<<lab::json_quote(f.id+"/bernstein_lange_precomp")<<"}\n";
 o<<prefix()<<",\"row_kind\":\"baseline_setup\",\"method\":\"bsgs_complete\",\"fixture\":"<<lab::json_quote(f.id)<<",\"targets_reusing_setup\":"<<targets.size()<<",\"counters\":"<<dec::cost_json(b.setup)<<",\"process_cpu_seconds\":"<<b.cpu<<",\"wall_seconds\":"<<b.wall<<",\"baby_steps\":"<<b.m<<",\"table_payload_bytes\":"<<b.baby.capacity()*sizeof(BSGS::Entry)<<",\"memory_scope\":\"Vector capacity payload; excludes object, allocator and sort stack\",\"setup_reference\":"<<lab::json_quote(f.id+"/bsgs_complete")<<"}\n";
}
int run(const std::string&fp,const std::string&tp,const std::string&output){lab::require(!std::filesystem::exists(output),"refusing output overwrite");const auto fixtures=dec::public_fixtures(fp);const auto targets=dec::public_targets(tp);std::map<std::string,std::vector<dec::Target>> grouped;for(const auto&t:targets)grouped[t.fixture].push_back(t);std::set<std::string> fids;for(const auto&f:fixtures)fids.insert(f.id);for(const auto&t:targets)lab::require(fids.contains(t.fixture),"target references unknown fixture");std::ofstream out(output);lab::require(bool(out),"cannot create output");out<<std::setprecision(21);U rows=0;
 for(const auto&f:fixtures){auto it=grouped.find(f.id);lab::require(it!=grouped.end()&&!it->second.empty(),"fixture has no targets");dec::Ops validation(f.c);Clock validation_timer;dec::validate_fixture(f,validation);for(const auto&t:it->second)lab::require(validation.valid(t.q)&&validation.scalar(t.q,static_cast<U>(f.r)).inf,"invalid target before setup");const auto validation_cpu=validation_timer.cpu(),validation_wall=validation_timer.wall();Hybrid h(f);Precomp p(f);BSGS b(f);setup_rows(out,f,it->second,h,p,b,validation.cost,validation_cpu,validation_wall);rows+=4;
  for(const auto&t:it->second){std::vector<unsigned> order{0,1,2,3,4};lab::RNG rng(nonzero_seed(f.seed^dec::hash("validation.arm-order.v1")^dec::mix(t.ordinal+0x991U)));for(std::size_t i=order.size();i>1;--i)std::swap(order[i-1],order[static_cast<std::size_t>(rng.bounded(i))]);unsigned pos=0;for(unsigned arm:order){if(arm==2)h.emit(out,f,t,pos);else if(arm<2){dec::Ops ops(f.c);const auto z=rho(f,t,ops,rho_seed(f,t));rho_row(out,f,t,arm==0?"rho_upstream_auto":"rho_upstream_auto_aa",pos,z);}else if(arm==3){const auto z=p.solve(f,t);common_target(out,f,t,"bernstein_lange_precomp",pos,z);out<<",\"setup_reference\":"<<lab::json_quote(f.id+"/bernstein_lange_precomp")<<"}\n";}else{const auto z=b.solve(f,t);common_target(out,f,t,"bsgs_complete",pos,z);out<<",\"setup_reference\":"<<lab::json_quote(f.id+"/bsgs_complete")<<"}\n";}++rows;++pos;}}
 }out.flush();lab::require(bool(out),"output write failure");std::cout<<"{\"rows\":"<<rows<<",\"fixtures\":"<<fixtures.size()<<",\"targets\":"<<targets.size()<<"}\n";return 0;}
int self_test(){unsigned checks=0;auto check=[&](bool b,const char*m){lab::require(b,m);++checks;};std::vector<lab::Fixture> fixtures{{"dev-small","ordinary",{17,2,2},{5,1,false},19,19,0x2915U},{"dev-rho","ordinary",{383,261,146},{196,297,false},181,362,0x1144U},{"dev-wide","ordinary",{65537,1,7},{13979,44364,false},13121,65605,0x1741U}};
 for(const auto&f:fixtures){dec::Ops o(f.c);dec::validate_fixture(f,o);Adapter a(f,o);ca_elem e=element(f.P),neg{};inv(&a.g,&neg,&e);canonical(&a.g,&e);canonical(&a.g,&neg);check(equal(&a.g,&e,&neg)!=0,"canonical negation quotient");check(hash_point(&a.g,&e)==hash_point(&a.g,&neg),"equal canonical point hashes");Precomp pc(f);BSGS bs(f);check(pc.status==CA_OK&&pc.table!=nullptr,"actual BL table builds");unsigned bl_hits=0;for(U k:{U{0},U{1},U{2},U{7},static_cast<U>(f.r-1)}){dec::Target t{f.id,"fixed-target",f.c.mul(f.P,k),k};dec::Ops x(f.c),y(f.c);const auto r=rho(f,t,x,0x112233U),aa=rho(f,t,y,0x112233U);check(r.scalar==k,"actual upstream rho recovers fixed public target");check(aa.scalar==r.scalar,"rho A/A answer matches");check(dec::cost_json(r.counters)==dec::cost_json(aa.counters),"rho A/A exact primitive path");const auto b=bs.solve(f,t);check(b.scalar==k,"complete BSGS recovers fixed target");const auto p=pc.solve(f,t);check(!p.scalar||*p.scalar==k,"BL returned witness is correct");if(p.scalar)++bl_hits;}check(bl_hits>=2,"nontrivial BL fixed-target recovery");}
 {const auto&f=fixtures[1];BSGS bs(f);for(U k=0;k<static_cast<U>(f.r);++k){dec::Target t{f.id,"exhaustive-development",f.c.mul(f.P,k),k};check(bs.solve(f,t).scalar==k,"complete BSGS exhaustive tiny subgroup");}check(ceil_sqrt(19)==5&&ceil_sqrt(181)==14&&ceil_sqrt(13121)==115,"public integer root budgets");}
 std::cout<<"{\"self_tests_passed\":"<<checks<<",\"scientific_cohort_run\":false,\"upstream_commit\":"<<lab::json_quote(upstream)<<"}\n";return 0;}
}
// Generic-group API glue for the custom shared-Ops vtable. These are the two
// required generic functions, without the library's optional EC fast backend.
extern "C" void ca_group_mul(const ca_group*g,ca_elem*r,const ca_elem*a,std::uint64_t k,std::uint64_t*count){auto&ops=*bench::adapter(g).ops;const auto before=ops.cost.group_additions;*r=bench::element(ops.scalar(bench::point(*a),k));if(count)*count+=ops.cost.group_additions-before;}
extern "C" int ca_check_members(const ca_group*g,const ca_elem*base,const ca_elem*target,std::uint64_t n,const char*){ca_elem p{},q{};ca_group_mul(g,&p,base,n,nullptr);ca_group_mul(g,&q,target,n,nullptr);return ca_group_is_identity(g,&p)&&ca_group_is_identity(g,&q);}
int main(int argc,char**argv){try{if(argc==2&&std::string(argv[1])=="--self-test")return bench::self_test();if(argc==5&&std::string(argv[1])=="--run")return bench::run(argv[2],argv[3],argv[4]);throw std::runtime_error("usage: baselines --self-test | --run FIXTURES PUBLIC_TARGETS FRESH_OUTPUT");}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
